-- Capture counters cover the complete maintained recovery projection, including non-sync records
CREATE TABLE recovery_source_stats (name TEXT PRIMARY KEY, rows INTEGER NOT NULL, bytes INTEGER NOT NULL, max_row_bytes INTEGER NOT NULL);
CREATE TABLE recovery_control (id INTEGER PRIMARY KEY CHECK(id=1), state TEXT NOT NULL CHECK(state IN ('open','closed','restoring','verified')), generation TEXT NOT NULL, snapshot_id TEXT, phase TEXT NOT NULL DEFAULT '', cursor INTEGER NOT NULL DEFAULT 0, ledger TEXT, code TEXT);
INSERT INTO recovery_control(id,state,generation) VALUES (1,'open',lower(hex(randomblob(16))));
CREATE TABLE service_snapshots (id TEXT PRIMARY KEY, source_generation TEXT NOT NULL, state TEXT NOT NULL, created_at INTEGER NOT NULL, ledger TEXT NOT NULL, secrets TEXT NOT NULL, rows INTEGER NOT NULL, bytes INTEGER NOT NULL, reserve INTEGER NOT NULL, cursor INTEGER NOT NULL DEFAULT 0, offset INTEGER NOT NULL DEFAULT 0, page INTEGER NOT NULL DEFAULT 0, manifest TEXT, code TEXT);
CREATE TABLE service_snapshot_rows (id INTEGER PRIMARY KEY, snapshot_id TEXT NOT NULL, table_name TEXT NOT NULL, source_rowid INTEGER NOT NULL, body TEXT NOT NULL, UNIQUE(snapshot_id,table_name,source_rowid));
CREATE INDEX service_snapshot_row_page ON service_snapshot_rows(snapshot_id,id);
CREATE TABLE service_snapshot_pins (snapshot_id TEXT NOT NULL, generation TEXT NOT NULL, PRIMARY KEY(snapshot_id,generation));
CREATE INDEX service_snapshot_generation ON service_snapshot_pins(generation,snapshot_id);
CREATE TABLE service_backup_objects (id TEXT PRIMARY KEY, identity TEXT NOT NULL, account_id TEXT, object_key TEXT NOT NULL UNIQUE, bucket TEXT NOT NULL CHECK(bucket IN ('backup','live')), size INTEGER NOT NULL, digest TEXT NOT NULL, seed TEXT NOT NULL, marker TEXT NOT NULL, seed_etag TEXT, state TEXT NOT NULL CHECK(state IN ('allocated','initializing','seeded','writing','ready','closing','closed','unsafe')), released INTEGER NOT NULL DEFAULT 0);
CREATE INDEX service_backup_dedup ON service_backup_objects(identity,state);
CREATE TABLE service_snapshot_objects (snapshot_id TEXT NOT NULL, ordinal INTEGER NOT NULL, source_key TEXT, object_id TEXT NOT NULL REFERENCES service_backup_objects(id), kind TEXT NOT NULL CHECK(kind IN ('cipher','page','index','manifest')), body TEXT, PRIMARY KEY(snapshot_id,ordinal), UNIQUE(snapshot_id,source_key));
CREATE INDEX service_snapshot_object_ref ON service_snapshot_objects(object_id,snapshot_id);
CREATE TABLE recovery_ledger_events (intent_id TEXT PRIMARY KEY, event TEXT NOT NULL);
CREATE TABLE recovery_liabilities (object_key TEXT PRIMARY KEY, marker TEXT NOT NULL, bytes INTEGER NOT NULL);
CREATE TABLE recovery_generations (original TEXT PRIMARY KEY, replacement TEXT NOT NULL UNIQUE);
CREATE TABLE recovery_object_map (original TEXT PRIMARY KEY, object_id TEXT NOT NULL REFERENCES service_backup_objects(id));
INSERT INTO recovery_source_stats SELECT 'email_jobs',COUNT(*),COALESCE(SUM(length(CAST(json_array(id,request_digest,request_id,payload,state,delivery,attempts,eligible,next_attempt_at,expires_at,created_at,updated_at,lease_token,lease_until,code,message_id,resend_of) AS BLOB))),0),COALESCE(MAX(length(CAST(json_array(id,request_digest,request_id,payload,state,delivery,attempts,eligible,next_attempt_at,expires_at,created_at,updated_at,lease_token,lease_until,code,message_id,resend_of) AS BLOB))),0) FROM email_jobs;
CREATE TRIGGER recovery_email_jobs_insert AFTER INSERT ON email_jobs BEGIN UPDATE recovery_source_stats SET rows=rows+1,bytes=bytes+length(CAST(json_array(NEW.id,NEW.request_digest,NEW.request_id,NEW.payload,NEW.state,NEW.delivery,NEW.attempts,NEW.eligible,NEW.next_attempt_at,NEW.expires_at,NEW.created_at,NEW.updated_at,NEW.lease_token,NEW.lease_until,NEW.code,NEW.message_id,NEW.resend_of) AS BLOB)),max_row_bytes=MAX(max_row_bytes,length(CAST(json_array(NEW.id,NEW.request_digest,NEW.request_id,NEW.payload,NEW.state,NEW.delivery,NEW.attempts,NEW.eligible,NEW.next_attempt_at,NEW.expires_at,NEW.created_at,NEW.updated_at,NEW.lease_token,NEW.lease_until,NEW.code,NEW.message_id,NEW.resend_of) AS BLOB))) WHERE name='email_jobs'; END;
CREATE TRIGGER recovery_email_jobs_delete AFTER DELETE ON email_jobs BEGIN UPDATE recovery_source_stats SET rows=rows-1,bytes=bytes-length(CAST(json_array(OLD.id,OLD.request_digest,OLD.request_id,OLD.payload,OLD.state,OLD.delivery,OLD.attempts,OLD.eligible,OLD.next_attempt_at,OLD.expires_at,OLD.created_at,OLD.updated_at,OLD.lease_token,OLD.lease_until,OLD.code,OLD.message_id,OLD.resend_of) AS BLOB)),max_row_bytes=MAX(max_row_bytes,length(CAST(json_array(OLD.id,OLD.request_digest,OLD.request_id,OLD.payload,OLD.state,OLD.delivery,OLD.attempts,OLD.eligible,OLD.next_attempt_at,OLD.expires_at,OLD.created_at,OLD.updated_at,OLD.lease_token,OLD.lease_until,OLD.code,OLD.message_id,OLD.resend_of) AS BLOB))) WHERE name='email_jobs'; END;
CREATE TRIGGER recovery_email_jobs_update AFTER UPDATE ON email_jobs BEGIN UPDATE recovery_source_stats SET bytes=bytes-length(CAST(json_array(OLD.id,OLD.request_digest,OLD.request_id,OLD.payload,OLD.state,OLD.delivery,OLD.attempts,OLD.eligible,OLD.next_attempt_at,OLD.expires_at,OLD.created_at,OLD.updated_at,OLD.lease_token,OLD.lease_until,OLD.code,OLD.message_id,OLD.resend_of) AS BLOB))+length(CAST(json_array(NEW.id,NEW.request_digest,NEW.request_id,NEW.payload,NEW.state,NEW.delivery,NEW.attempts,NEW.eligible,NEW.next_attempt_at,NEW.expires_at,NEW.created_at,NEW.updated_at,NEW.lease_token,NEW.lease_until,NEW.code,NEW.message_id,NEW.resend_of) AS BLOB)),max_row_bytes=MAX(max_row_bytes,length(CAST(json_array(NEW.id,NEW.request_digest,NEW.request_id,NEW.payload,NEW.state,NEW.delivery,NEW.attempts,NEW.eligible,NEW.next_attempt_at,NEW.expires_at,NEW.created_at,NEW.updated_at,NEW.lease_token,NEW.lease_until,NEW.code,NEW.message_id,NEW.resend_of) AS BLOB))) WHERE name='email_jobs'; END;
