-- Restore fragments stay invisible until every authenticated row has been assembled
CREATE TABLE recovery_fragments (table_name TEXT NOT NULL, source_rowid INTEGER NOT NULL, offset INTEGER NOT NULL, total INTEGER NOT NULL, body TEXT NOT NULL, PRIMARY KEY(table_name,source_rowid,offset));
CREATE TABLE recovery_import_rows (id INTEGER PRIMARY KEY, table_name TEXT NOT NULL, source_rowid INTEGER NOT NULL, body TEXT NOT NULL, UNIQUE(table_name,source_rowid));
CREATE TRIGGER snapshot_rows_immutable BEFORE UPDATE ON service_snapshot_rows BEGIN SELECT RAISE(ABORT,'snapshot_immutable'); END;

-- Complete global logical metadata liabilities for durable non-sync source rows
UPDATE quota_counters SET metadata_bytes=metadata_bytes+(SELECT COALESCE(SUM(length(CAST(json_array(id,normalized_email,delivery_email,username,verified_at,access,revision,capacity_bytes,created_at,session_epoch,username_withheld) AS BLOB))),0) FROM accounts),metadata_rows=metadata_rows+(SELECT COUNT(*) FROM accounts) WHERE scope='global';
CREATE TRIGGER recovery_charge_accounts_insert AFTER INSERT ON accounts BEGIN UPDATE quota_counters SET metadata_bytes=metadata_bytes+length(CAST(json_array(NEW.id,NEW.normalized_email,NEW.delivery_email,NEW.username,NEW.verified_at,NEW.access,NEW.revision,NEW.capacity_bytes,NEW.created_at,NEW.session_epoch,NEW.username_withheld) AS BLOB)),metadata_rows=metadata_rows+1 WHERE scope='global'; END;
CREATE TRIGGER recovery_charge_accounts_delete AFTER DELETE ON accounts BEGIN UPDATE quota_counters SET metadata_bytes=metadata_bytes-length(CAST(json_array(OLD.id,OLD.normalized_email,OLD.delivery_email,OLD.username,OLD.verified_at,OLD.access,OLD.revision,OLD.capacity_bytes,OLD.created_at,OLD.session_epoch,OLD.username_withheld) AS BLOB)),metadata_rows=metadata_rows-1 WHERE scope='global'; END;
CREATE TRIGGER recovery_charge_accounts_update AFTER UPDATE ON accounts BEGIN UPDATE quota_counters SET metadata_bytes=metadata_bytes-length(CAST(json_array(OLD.id,OLD.normalized_email,OLD.delivery_email,OLD.username,OLD.verified_at,OLD.access,OLD.revision,OLD.capacity_bytes,OLD.created_at,OLD.session_epoch,OLD.username_withheld) AS BLOB))+length(CAST(json_array(NEW.id,NEW.normalized_email,NEW.delivery_email,NEW.username,NEW.verified_at,NEW.access,NEW.revision,NEW.capacity_bytes,NEW.created_at,NEW.session_epoch,NEW.username_withheld) AS BLOB)) WHERE scope='global'; END;
UPDATE quota_counters SET metadata_bytes=metadata_bytes+(SELECT COALESCE(SUM(length(CAST(json_array(account_id,role,credential_id,record,account_envelope,revision) AS BLOB))),0) FROM credentials),metadata_rows=metadata_rows+(SELECT COUNT(*) FROM credentials) WHERE scope='global';
