-- Conservative opaque envelopes cover control/stat rows and each quota identity without recursive self-accounting
UPDATE quota_counters SET reserved_metadata=reserved_metadata+16384+(SELECT COUNT(*)*256 FROM quota_counters) WHERE scope='global';
CREATE TRIGGER recovery_quota_identity_insert AFTER INSERT ON quota_counters WHEN NEW.scope<>'global' BEGIN UPDATE quota_counters SET reserved_metadata=reserved_metadata+256 WHERE scope='global'; END;
CREATE TRIGGER recovery_quota_identity_delete AFTER DELETE ON quota_counters WHEN OLD.scope<>'global' BEGIN UPDATE quota_counters SET reserved_metadata=reserved_metadata-256 WHERE scope='global'; END;
CREATE TRIGGER recovery_ledger_charge_insert AFTER INSERT ON recovery_ledger_events BEGIN UPDATE quota_counters SET metadata_bytes=metadata_bytes+length(CAST(json_array(NEW.intent_id,NEW.event) AS BLOB)),metadata_rows=metadata_rows+1 WHERE scope='global'; END;
CREATE TRIGGER recovery_ledger_charge_delete AFTER DELETE ON recovery_ledger_events BEGIN UPDATE quota_counters SET metadata_bytes=metadata_bytes-length(CAST(json_array(OLD.intent_id,OLD.event) AS BLOB)),metadata_rows=metadata_rows-1 WHERE scope='global'; END;
CREATE TRIGGER recovery_ledger_immutable BEFORE UPDATE ON recovery_ledger_events BEGIN SELECT RAISE(ABORT,'recovery_ledger_immutable'); END;
CREATE TRIGGER recovery_object_identity BEFORE UPDATE ON service_backup_objects WHEN NEW.id IS NOT OLD.id OR NEW.identity IS NOT OLD.identity OR NEW.object_key IS NOT OLD.object_key OR NEW.bucket IS NOT OLD.bucket OR NEW.size IS NOT OLD.size OR NEW.digest IS NOT OLD.digest OR NEW.seed IS NOT OLD.seed OR NEW.marker IS NOT OLD.marker OR (OLD.seed_etag IS NOT NULL AND NEW.seed_etag IS NOT OLD.seed_etag) OR NEW.released<OLD.released BEGIN SELECT RAISE(ABORT,'recovery_object_immutable'); END;
CREATE TRIGGER recovery_snapshot_identity BEFORE UPDATE ON service_snapshots WHEN NEW.id IS NOT OLD.id OR NEW.source_generation IS NOT OLD.source_generation OR NEW.created_at IS NOT OLD.created_at OR NEW.ledger IS NOT OLD.ledger OR NEW.secrets IS NOT OLD.secrets OR NEW.rows IS NOT OLD.rows OR NEW.bytes IS NOT OLD.bytes BEGIN SELECT RAISE(ABORT,'snapshot_immutable'); END;
